function uniqueSuggestions(values) {
  const seen = new Set();
  return values.filter(Boolean).map(v=>String(v).trim()).filter(v=>{
    const key = normalizeName(v);
    if (!key || seen.has(key)) return false;
    seen.add(key); return true;
  }).sort((a,b)=>a.localeCompare(b, 'pt-BR'));
}

function renderAutocompleteLists() {
  const restaurants = uniqueSuggestions([
    ...RESTAURANT_SUGGESTIONS,
    ...(state.history || []).map(r=>r.restaurantName),
    ...(state.days || []).flatMap(d=>(d.activities||[]).map(a=>a.restaurant || a.venue || a.restaurantName))
  ]);
  const meals = uniqueSuggestions([
    ...MEAL_SUGGESTIONS,
    ...(state.history || []).map(r=>r.mealItem)
  ]);
  const attractions = uniqueSuggestions([
    ...ATTRACTION_SUGGESTIONS,
    ...(state.days || []).flatMap(d=>(d.activities||[]).filter(a=>a.type==='attraction').map(a=>a.title)),
    ...Object.values(state.liveCache || {}).flatMap(payload=>(payload?.liveData || []).map(x=>x.name))
  ]);
  const write = (id, values) => { const el=$(id); if (el) el.innerHTML = values.map(v=>`<option value="${escapeHtml(v)}"></option>`).join(''); };
  write('#restaurantSuggestions', restaurants);
  write('#mealSuggestions', meals);
  write('#attractionSuggestions', attractions);
}

function normalizeRating(value) {
  const n = Number(value || 0);
  if (!Number.isFinite(n) || n <= 0) return 0;
  return Math.max(.5, Math.min(5, Math.round(n * 2) / 2));
}

function formatRating(value, includeNumber = false) {
  const rating = normalizeRating(value);
  if (!rating) return '';
  const full = Math.floor(rating);
  const half = rating % 1 >= .5;
  const visual = `${'★'.repeat(full)}${half ? '½' : ''}`;
  return includeNumber ? `${visual} ${rating.toFixed(1).replace('.', ',')}` : visual;
}

function saveState() {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
}

function snapshotOriginalPlans(days = state.days) {
  const plans = {};
  for (const day of days || []) {
    plans[day.date] = (day.activities || []).map((activity, index) => ({
      ...structuredClone(activity),
      originalIndex: index,
      replanDeferred: false
    }));
  }
  return plans;
}

function ensureOriginalPlans() {
  if (!state.originalPlans || typeof state.originalPlans !== 'object') state.originalPlans = {};
  for (const day of state.days || []) {
    if (!Array.isArray(state.originalPlans[day.date])) {
      state.originalPlans[day.date] = (day.activities || []).map((activity, index) => ({
        ...structuredClone(activity),
        originalIndex: index,
        replanDeferred: false
      }));
    }
  }
  if (!state.replanDecisions || typeof state.replanDecisions !== 'object') state.replanDecisions = {};
  if (!Array.isArray(state.replanHistory)) state.replanHistory = [];
  if (!state.lastReplanAnalyses || typeof state.lastReplanAnalyses !== 'object') state.lastReplanAnalyses = {};
  if (!state.movementByDate || typeof state.movementByDate !== 'object') state.movementByDate = {};
}

function getOriginalActivities(day) {
  ensureOriginalPlans();
  return state.originalPlans[day?.date] || day?.activities || [];
}

function getParkThemeConfig(parkKey = state.selectedPark) {
  return PARK_THEMES[parkKey] || PARK_THEMES['off-day'];
}

function applyParkTheme() {
  const selectedDay = getSelectedDay();
  const parkKey = state.selectedPark || selectedDay?.park || 'off-day';
  const config = getParkThemeConfig(parkKey);
  document.documentElement.dataset.parkTheme = parkKey;
  document.documentElement.dataset.brand = config.brand;

  const family = $('#parkFamilyLabel');
  const name = $('#parkThemeName');
  const cue = $('#parkThemeCue');
  if (family) family.textContent = config.family;
  if (name) name.textContent = PARKS[parkKey]?.name || 'Orlando';
  if (cue) cue.textContent = config.cue;
  renderParkIcons(parkKey);
}

function applyTheme() {
  const dark = Boolean(state.settings?.darkMode);
  const config = getParkThemeConfig(document.documentElement.dataset.parkTheme || state.selectedPark);
  document.documentElement.dataset.theme = dark ? 'dark' : 'light';
  document.documentElement.style.colorScheme = dark ? 'dark' : 'light';
  const themeMeta = document.querySelector('meta[name="theme-color"]');
  if (themeMeta) themeMeta.setAttribute('content', dark ? config.themeColor.dark : config.themeColor.light);

  const button = $('#themeToggleBtn');
  if (button) {
    button.setAttribute('aria-pressed', String(dark));
    button.setAttribute('aria-label', dark ? 'Desativar modo escuro' : 'Ativar modo escuro');
    button.title = dark ? 'Desativar modo escuro' : 'Ativar modo escuro';
  }
}

async function loadState() {
  const stored = localStorage.getItem(STORAGE_KEY);
  if (stored) {
    try {
      const parsed = JSON.parse(stored);
      state = {
        ...structuredClone(DEFAULT_STATE),
        ...parsed,
        settings: { ...DEFAULT_STATE.settings, ...(parsed.settings || {}) }
      };
    }
    catch { state = structuredClone(DEFAULT_STATE); }
  }
  if (!state.days?.length) await loadDemo(false);
  if (!state.selectedDate || !state.days.some(d => d.date === state.selectedDate)) {
    state.selectedDate = chooseRelevantDate();
  }
  const selectedDay = getSelectedDay();
  if (selectedDay?.park) state.selectedPark = selectedDay.park;
  ensureOriginalPlans();
  saveState();
}

async function loadDemo(showMessage = true) {
  const response = await fetch('./data/sample-itinerary.json');
  const demo = await response.json();
  state.tripName = demo.tripName;
  state.timezone = demo.timezone || ORLANDO_TZ;
  state.settings = { ...state.settings, ...(demo.settings || {}) };
  state.days = demo.days || [];
  state.history = [];
  state.stepsByDate = {};
  state.movementByDate = {};
  state.originalPlans = snapshotOriginalPlans(state.days);
  state.replanDecisions = {};
  state.replanHistory = [];
  state.lastReplanAnalyses = {};
  state.selectedDate = chooseRelevantDate();
  state.selectedPark = state.days[0]?.park || 'magic-kingdom';
  saveState();
  if (showMessage) toast('Roteiro de demonstração restaurado.');
}

function chooseRelevantDate() {
  if (!state.days?.length) return null;
  const today = getOrlandoParts().date;
  return state.days.find(d => d.date === today)?.date || state.days.find(d => d.date > today)?.date || state.days.at(-1).date;
}

function getOrlandoParts(date = new Date()) {
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone: state.timezone || ORLANDO_TZ,
    year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit', hourCycle: 'h23'
  }).formatToParts(date).reduce((acc, p) => (acc[p.type] = p.value, acc), {});
  return { date: `${parts.year}-${parts.month}-${parts.day}`, hour: +parts.hour, minute: +parts.minute, second: +parts.second, time: `${parts.hour}:${parts.minute}` };
}

function timeToMinutes(t) {
  const [h,m] = String(t || '00:00').split(':').map(Number);
  return h * 60 + m;
}

function minutesToTime(total) {
  const safe = Math.max(0, Math.min(1439, Math.round(Number(total || 0) / 5) * 5));
  return `${String(Math.floor(safe / 60)).padStart(2,'0')}:${String(safe % 60).padStart(2,'0')}`;
}

function ensureMovementRecord(date = getOrlandoParts().date) {
  if (!state.movementByDate || typeof state.movementByDate !== 'object') state.movementByDate = {};
  if (!state.movementByDate[date]) {
    state.movementByDate[date] = { distanceMeters:0, acceptedPoints:0, rejectedPoints:0, updatedAt:null };
  }
  return state.movementByDate[date];
}

function haversineMeters(a, b) {
  const R = 6371000;
  const toRad = value => value * Math.PI / 180;
  const dLat = toRad(b.lat - a.lat);
  const dLon = toRad(b.lon - a.lon);
  const lat1 = toRad(a.lat);
  const lat2 = toRad(b.lat);
  const h = Math.sin(dLat/2) ** 2 + Math.cos(lat1) * Math.cos(lat2) * Math.sin(dLon/2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(h));
}

function movementMetricsForDate(date) {
  const record = state.movementByDate?.[date];
  const strideMeters = Math.max(.4, Math.min(1.2, Number(state.settings.strideCm || 75) / 100));
  let distanceMeters = Number(record?.distanceMeters || 0);
  let steps = distanceMeters > 0 ? Math.round(distanceMeters / strideMeters) : 0;

  // Backward compatibility for older backups that only stored manually entered steps.
  const legacySteps = Number(state.stepsByDate?.[date] || 0);
  if (!distanceMeters && legacySteps) {
    steps = legacySteps;
    distanceMeters = legacySteps * strideMeters;
  }

  const distanceKm = distanceMeters / 1000;
  const weightKg = Number(state.settings.weightKg || 0);
  // Deliberately labeled as an estimate in the UI; walking energy varies by person, pace and terrain.
  const calories = weightKg > 0 && distanceKm > 0 ? Math.round(distanceKm * weightKg * 0.5) : null;
  return { distanceMeters, distanceKm, steps, calories, record };
}

function movementMetricsForScope(scope = 'day') {
  const dates = scope === 'trip'
    ? [...new Set([...(state.days || []).map(d=>d.date), ...Object.keys(state.movementByDate || {}), ...Object.keys(state.stepsByDate || {})])]
    : [state.selectedDate];
  return dates.filter(Boolean).reduce((acc,date) => {
    const m = movementMetricsForDate(date);
    acc.distanceMeters += m.distanceMeters;
    acc.steps += m.steps;
    if (m.calories != null) acc.calories = (acc.calories ?? 0) + m.calories;
    return acc;
  }, { distanceMeters:0, steps:0, calories:null });
}

function formatDistance(meters) {
  const km = Number(meters || 0) / 1000;
  if (!km) return '0 km';
  return `${km < 10 ? km.toFixed(2) : km.toFixed(1)} km`;
}

function handleGpsPosition(position) {
  const coords = position.coords;
  const point = {
    lat: Number(coords.latitude),
    lon: Number(coords.longitude),
    accuracy: Number(coords.accuracy || 999),
    ts: Number(position.timestamp || Date.now())
  };
  const date = getOrlandoParts(new Date(point.ts)).date;
  const record = ensureMovementRecord(date);

  if (!Number.isFinite(point.lat) || !Number.isFinite(point.lon) || point.accuracy > 80) {
    record.rejectedPoints = Number(record.rejectedPoints || 0) + 1;
    gpsSignalStatus = point.accuracy > 80 ? `sinal fraco (±${Math.round(point.accuracy)} m)` : 'leitura inválida';
    renderMovement();
    return;
  }

  gpsSignalStatus = `GPS ativo (±${Math.round(point.accuracy)} m)`;
  if (gpsLastPoint) {
    const distance = haversineMeters(gpsLastPoint, point);
    const seconds = Math.max(1, (point.ts - gpsLastPoint.ts) / 1000);
    // Reject GPS jitter and implausible jumps. 12 m/s is already far above normal walking pace.
    const plausibleMax = Math.max(120, seconds * 12);
    if (distance >= 2 && distance <= plausibleMax) {
      record.distanceMeters = Number(record.distanceMeters || 0) + distance;
      record.acceptedPoints = Number(record.acceptedPoints || 0) + 1;
      record.updatedAt = new Date(point.ts).toISOString();
    } else if (distance > plausibleMax) {
      record.rejectedPoints = Number(record.rejectedPoints || 0) + 1;
    }
  } else {
    record.acceptedPoints = Number(record.acceptedPoints || 0) + 1;
    record.updatedAt = new Date(point.ts).toISOString();
  }

  gpsLastPoint = point;
  if (Date.now() - gpsLastPersistAt > 5000) {
    gpsLastPersistAt = Date.now();
    saveState();
  }
  renderMovement();
  renderReport();
  renderHistory();
}

function handleGpsError(error) {
  const messages = {
    1: 'Permissão de localização negada.',
    2: 'Localização indisponível no momento.',
    3: 'Tempo limite ao obter localização.'
  };
  gpsSignalStatus = messages[error?.code] || 'Não foi possível acessar o GPS.';
  if (error?.code === 1) stopGpsTracking(false);
  renderMovement();
  toast(gpsSignalStatus);
}

function startGpsTracking() {
  if (!('geolocation' in navigator)) {
    toast('Este navegador não oferece geolocalização.');
    return;
  }
  if (!window.isSecureContext && !['localhost','127.0.0.1'].includes(location.hostname)) {
    toast('O GPS precisa de HTTPS. Em testes no computador, use localhost.');
    return;
  }
  if (gpsWatchId != null) return;
  gpsLastPoint = null;
  gpsSignalStatus = 'aguardando sinal GPS…';
  renderMovement();
  gpsWatchId = navigator.geolocation.watchPosition(
    handleGpsPosition,
    handleGpsError,
    { enableHighAccuracy:true, maximumAge:5000, timeout:20000 }
  );
}

function stopGpsTracking(showMessage = true) {
  if (gpsWatchId != null && navigator.geolocation) navigator.geolocation.clearWatch(gpsWatchId);
  gpsWatchId = null;
  gpsLastPoint = null;
  gpsSignalStatus = 'GPS pausado';
  saveState();
  renderMovement();
  if (showMessage) toast('Rastreamento GPS pausado.');
}

function toggleGpsTracking() {
  if (gpsWatchId == null) startGpsTracking();
  else stopGpsTracking();
}

function resetMovementForToday() {
  const date = getOrlandoParts().date;
  if (!confirm('Zerar a distância, passos e calorias estimadas de hoje?')) return;
  state.movementByDate[date] = { distanceMeters:0, acceptedPoints:0, rejectedPoints:0, updatedAt:null };
  state.stepsByDate[date] = 0;
  gpsLastPoint = null;
  saveState();
  renderAll();
  toast('Movimento de hoje zerado.');
}

function renderMovement() {
  const el = $('#movementStrip');
  if (!el) return;
  const today = getOrlandoParts().date;
  const m = movementMetricsForDate(today);
  const active = gpsWatchId != null;
  $('#movementHeadline').textContent = `${formatDistance(m.distanceMeters)} · ${m.steps.toLocaleString('pt-BR')} passos`;
  const kcalText = m.calories == null ? 'calorias: configure o peso' : `~${m.calories.toLocaleString('pt-BR')} kcal`;
  $('#movementDetail').textContent = `${gpsSignalStatus} · ${kcalText}`;
  $('#gpsToggleBtn').textContent = active ? 'Pausar GPS' : 'Iniciar GPS';
  $('#gpsToggleBtn').classList.toggle('active', active);
  const settingsBtn = $('#gpsSettingsBtn');
  if (settingsBtn) settingsBtn.textContent = active ? 'Pausar GPS' : 'Iniciar GPS';
}

function formatDate(dateStr, compact = false) {
  const [y,m,d] = dateStr.split('-').map(Number);
  return new Intl.DateTimeFormat('pt-BR', compact ? { day:'2-digit', month:'2-digit' } : { weekday:'short', day:'2-digit', month:'short' }).format(new Date(y, m-1, d));
}

function formatTimeISO(iso) {
  if (!iso) return '--:--';
  const date = new Date(iso);
  return new Intl.DateTimeFormat('pt-BR', { timeZone: state.timezone || ORLANDO_TZ, hour:'2-digit', minute:'2-digit' }).format(date);
}

function getSelectedDay() { return state.days.find(d => d.date === state.selectedDate); }
function getDayHistory(date = state.selectedDate) { return state.history.filter(h => h.date === date && h.status === 'done'); }
function getActivityLog(id) { return state.history.find(h => h.activityId === id && h.status !== 'skipped'); }
function isDone(id) { return state.history.some(h => h.activityId === id && h.status === 'done'); }
function isSkipped(id) { return state.history.some(h => h.activityId === id && h.status === 'skipped'); }
function isStarted(id) { return state.history.some(h => h.activityId === id && h.status === 'started'); }

function currentPlanStatus(day) {
  const now = getOrlandoParts();
  const activities = day?.activities || [];
  const pending = activities.filter(a => !isDone(a.id) && !isSkipped(a.id));
  const activePending = pending.filter(a => !a.replanDeferred);
  const done = activities.length - pending.length;
  if (!day || !activities.length) return { status:'Sem roteiro', detail:'Importe um roteiro para começar.', delay:0, done, pending:0, level:'ok' };
  if (day.date < now.date) return { status:'Dia encerrado', detail:`${done} de ${activities.length} atividades registradas.`, delay:0, done, pending:pending.length, level:'ok' };
  if (day.date > now.date) return { status:'Roteiro futuro', detail:`Próximo dia em ${formatDate(day.date)}.`, delay:0, done, pending:pending.length, level:'ok' };
  if (!activePending.length && pending.length) return { status:'Plano principal concluído', detail:`${pending.length} opção(ões) ficaram para o fim do dia.`, delay:0, done, pending:pending.length, level:'ok' };
  if (!pending.length) return { status:'Tudo concluído', detail:'O roteiro planejado foi encerrado. Aproveitem o resto do dia!', delay:0, done, pending:0, level:'ok' };
  const next = activePending[0];
  const delay = (now.hour * 60 + now.minute) - timeToMinutes(next.time);
  const threshold = Number(state.settings.delayThreshold || 15);
  if (delay > threshold) return { status:`${delay} min atrasados`, detail:`${next.title} estava previsto para ${next.time}. Vale replanejar o restante do dia.`, delay, done, pending:pending.length, level:'bad', next };
  if (delay < -threshold) return { status:`${Math.abs(delay)} min adiantados`, detail:`Vocês ganharam uma janela antes de ${next.title}.`, delay, done, pending:pending.length, level:'ok', next };
  return { status:'No ritmo', detail:`Próxima atividade: ${next.title} às ${next.time}.`, delay, done, pending:pending.length, level:'ok', next };
}

function normalizeName(v='') {
  return v.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[™®'’]/g,'').replace(/[^a-z0-9]+/g,' ').trim();
}

function findLiveMatch(activity, liveData) {
  const target = normalizeName(activity.entityName || activity.title);
  if (!target) return null;
  let exact = liveData.find(x => normalizeName(x.name) === target);
  if (exact) return exact;
  return liveData.find(x => {
    const n = normalizeName(x.name);
    return n.includes(target) || target.includes(n);
  }) || null;
}

function extractStandby(entry) {
  const raw = entry?.queue?.STANDBY?.waitTime;
  return Number.isFinite(raw) ? raw : null;
}

function weatherCodeText(code) {
  if (code == null) return 'sem leitura';
  if (code === 0) return 'céu limpo';
  if ([1,2,3].includes(code)) return 'nuvens';
  if ([45,48].includes(code)) return 'neblina';
  if ([51,53,55,56,57].includes(code)) return 'garoa';
  if ([61,63,65,66,67,80,81,82].includes(code)) return 'chuva';
  if ([95,96,99].includes(code)) return 'trovoadas';
  return 'tempo variável';
}

function weatherRiskForHour(hour) {
  if (!hour) return { level:'low', score:0, label:'baixo' };
  const storm = [95,96,99].includes(hour.weather_code);
  const precip = Number(hour.precipitation_probability || 0);
  const gust = Number(hour.wind_gusts_10m || 0);
  if (storm || precip >= 70 || gust >= 55) return { level:'high', score:2, label:'alto' };
  if (precip >= 45 || gust >= 40 || [61,63,65,80,81,82].includes(hour.weather_code)) return { level:'medium', score:1, label:'médio' };
  return { level:'low', score:0, label:'baixo' };
}

async function fetchWeather(parkKey = state.selectedPark) {
  const park = PARKS[parkKey] || PARKS['off-day'];
  const url = `${WEATHER_BASE}?latitude=${park.lat}&longitude=${park.lon}&current=temperature_2m,weather_code,precipitation&hourly=temperature_2m,precipitation_probability,weather_code,wind_gusts_10m&timezone=${encodeURIComponent(state.timezone || ORLANDO_TZ)}&forecast_days=2`;
  try {
    const res = await fetch(url, { headers: { 'Accept':'application/json' } });
    if (!res.ok) throw new Error(`Weather HTTP ${res.status}`);
    const data = await res.json();
    const hours = (data.hourly?.time || []).map((time,i) => ({
      time,
      temperature_2m: data.hourly.temperature_2m?.[i],
      precipitation_probability: data.hourly.precipitation_probability?.[i],
      weather_code: data.hourly.weather_code?.[i],
      wind_gusts_10m: data.hourly.wind_gusts_10m?.[i]
    }));
    const payload = { fetchedAt: Date.now(), current: data.current, hours };
    state.weatherCache[parkKey] = payload;
    saveState();
    return payload;
  } catch (err) {
    return state.weatherCache[parkKey] || null;
  }
}

async function fetchLive(parkKey = state.selectedPark) {
  const park = PARKS[parkKey];
  if (!park?.entityId) return null;
  try {
    const res = await fetch(`${API_BASE}/entity/${park.entityId}/live`, { headers: { 'Accept':'application/json' } });
    if (!res.ok) throw new Error(`Live HTTP ${res.status}`);
    const data = await res.json();
    const payload = { fetchedAt: Date.now(), liveData: data.liveData || [] };
    state.liveCache[parkKey] = payload;
    saveState();
    return payload;
  } catch (err) {
    return state.liveCache[parkKey] || null;
  }
}

function relevantWeather(weather) {
  if (!weather) return { current:null, nextRisk:null, risk:{level:'low',score:0,label:'--'} };
  const now = getOrlandoParts();
  const prefix = `${now.date}T`;
  const nowMin = now.hour*60 + now.minute;
  const todayHours = weather.hours.filter(h => h.time.startsWith(prefix));
  const currentHour = todayHours.reduce((best,h) => {
    const hm = h.time.slice(11,16);
    return timeToMinutes(hm) <= nowMin ? h : best;
  }, todayHours[0]);
  const nextRisk = todayHours.find(h => timeToMinutes(h.time.slice(11,16)) >= nowMin && weatherRiskForHour(h).score > 0) || null;
  return { current:currentHour, nextRisk, risk: weatherRiskForHour(currentHour) };
}

function nextFixedActivity(day) {
  const now = getOrlandoParts();
  const nowMin = now.hour*60 + now.minute;
  return (day?.activities || []).find(a => !a.flexible && !a.replanDeferred && !isDone(a.id) && !isSkipped(a.id) && timeToMinutes(a.time) > nowMin) || null;
}

function optimizeCandidates(day, livePayload, weatherPayload) {
  if (!day || !livePayload) return [];
  const now = getOrlandoParts();
  const nowMin = now.hour*60 + now.minute;
  const live = livePayload.liveData || [];
  const weather = relevantWeather(weatherPayload);
  const fixed = nextFixedActivity(day);
  const minutesToFixed = fixed ? timeToMinutes(fixed.time) - nowMin : Infinity;
  const lastDone = [...getDayHistory(day.date)].sort((a,b) => (b.actualEnd||'').localeCompare(a.actualEnd||''))[0];
  const lastActivity = day.activities.find(a => a.id === lastDone?.activityId);

  return day.activities
    .filter(a => a.flexible && a.type === 'attraction' && !isDone(a.id) && !isSkipped(a.id))
    .map(a => {
      const match = findLiveMatch(a, live);
      const wait = extractStandby(match);
      if (wait == null) return null;
      const planned = timeToMinutes(a.time);
      const riskNow = weather.risk.score;
      let score = Number(a.priority || 3) * 20 - wait * .65;
      const reasons = [];
      const timeNeed = wait + Number(a.duration || 10) + 10;
      if (timeNeed > minutesToFixed) return null;
      if (wait <= 20) { score += 18; reasons.push(`fila baixa (${wait} min)`); }
      else if (wait <= 40) { score += 8; reasons.push(`fila aceitável (${wait} min)`); }
      else if (wait >= Number(state.settings.longWaitThreshold || 60)) { score -= 18; reasons.push(`fila alta (${wait} min)`); }
      if (a.weatherSensitive && weather.nextRisk && riskNow === 0) { score += 18; reasons.push('vale fazer antes da piora do tempo'); }
      if (a.weatherSensitive && riskNow > 0) { score -= 30; reasons.push('exposta ao mau tempo agora'); }
      if (a.indoor && riskNow > 0) { score += 18; reasons.push('boa opção coberta agora'); }
      if (lastActivity?.area && a.area === lastActivity.area) { score += 9; reasons.push('reduz deslocamento'); }
      if (planned < nowMin) { score += Math.min(12, (nowMin-planned) * .08); reasons.push('já estava prevista'); }
      return { activity:a, live:match, wait, score, reasons };
    })
    .filter(Boolean)
    .sort((a,b) => b.score - a.score)
    .slice(0,3);
}

function getReplanTriggers(day, livePayload, weatherPayload) {
  if (!day) return [];
  const triggers = [];
  const now = getOrlandoParts();
  const status = currentPlanStatus(day);
  const delayThreshold = Number(state.settings.delayThreshold || 15);
  const longWait = Number(state.settings.longWaitThreshold || 60);

  if (day.date === now.date && status.delay > delayThreshold) {
    triggers.push({ type:'delay', severity:'high', label:`${status.delay} min de atraso`, value:status.delay });
  }

  const skippedAttractions = (day.activities || [])
    .filter(a => a.type === 'attraction' && isSkipped(a.id) && !isDone(a.id));
  for (const activity of skippedAttractions.slice(0, 3)) {
    const skippedLog = state.history.find(h => h.activityId === activity.id && h.status === 'skipped');
    triggers.push({
      type:'skipped',
      severity:'medium',
      label:`${activity.title} pulada · buscando novo encaixe`,
      activityId:activity.id,
      value:skippedLog?.actualEnd || activity.id
    });
  }

  const live = livePayload?.liveData || [];
  const longWaits = (day.activities || [])
    .filter(a => a.type === 'attraction' && !a.replanDeferred && !isDone(a.id) && !isSkipped(a.id))
    .map(a => ({ activity:a, wait:extractStandby(findLiveMatch(a, live)) }))
    .filter(x => x.wait != null && x.wait >= longWait)
    .sort((a,b) => b.wait - a.wait);
  if (longWaits.length) {
    const first = longWaits[0];
    triggers.push({ type:'wait', severity:'medium', label:`${first.activity.title}: ${first.wait} min`, activityId:first.activity.id, value:first.wait });
  }

  const weather = relevantWeather(weatherPayload);
  const nowMin = now.hour * 60 + now.minute;
  if (weather.risk.score > 0) {
    triggers.push({ type:'weather', severity:weather.risk.level === 'high' ? 'high' : 'medium', label:`Risco de tempo ${weather.risk.label} agora`, value:weather.risk.score });
  } else if (weather.nextRisk) {
    const riskMin = timeToMinutes(weather.nextRisk.time.slice(11,16));
    if (riskMin >= nowMin && riskMin - nowMin <= 180) {
      triggers.push({ type:'weather', severity:'medium', label:`Tempo pode piorar às ${weather.nextRisk.time.slice(11,16)}`, value:weather.nextRisk.time });
    }
  }
  return triggers;
}

function replanSignature(day, triggers) {
  const parts = triggers.map(t => {
    if (t.type === 'delay') return `delay:${Math.floor(Number(t.value || 0) / 15)}`;
    if (t.type === 'wait') return `wait:${t.activityId}:${Math.floor(Number(t.value || 0) / 15)}`;
    if (t.type === 'skipped') return `skipped:${t.activityId}:${String(t.value || '').slice(0,16)}`;
    return `weather:${String(t.value || t.label)}`;
  });
  return `${day?.date || 'none'}|${parts.sort().join('|')}`;
}

function weatherAtMinute(weatherPayload, minute, date = getOrlandoParts().date) {
  if (!weatherPayload?.hours?.length) return null;
  const target = Math.max(0, Math.min(1439, Number(minute || 0)));
  const sameDay = weatherPayload.hours.filter(h => h.time.startsWith(`${date}T`));
  if (!sameDay.length) return null;
  return sameDay.reduce((best, hour) => {
    const hm = timeToMinutes(hour.time.slice(11,16));
    return Math.abs(hm - target) < Math.abs(timeToMinutes(best.time.slice(11,16)) - target) ? hour : best;
  }, sameDay[0]);
}

function activityCoordinates(activity) {
  const lat = Number(activity?.lat ?? activity?.latitude);
  const lon = Number(activity?.lon ?? activity?.lng ?? activity?.longitude);
  return Number.isFinite(lat) && Number.isFinite(lon) ? {lat,lon} : null;
}

function proximityMeta(activity, previousActivity, nextActivity) {
  let score = 0;
  const reasons = [];
  const area = normalizeName(activity?.area || '');
  for (const [neighbor, label] of [[previousActivity,'atividade anterior'],[nextActivity,'próxima atividade']]) {
    if (!neighbor) continue;
    const neighborArea = normalizeName(neighbor.area || '');
    if (area && neighborArea && area === neighborArea) {
      score += label === 'próxima atividade' ? 16 : 10;
      reasons.push(`fica na mesma área da ${label}`);
      continue;
    }
    const a = activityCoordinates(activity);
    const b = activityCoordinates(neighbor);
    if (a && b) {
      const meters = haversineMeters(a,b);
      if (meters <= 350) { score += 14; reasons.push(`fica a cerca de ${Math.round(meters/50)*50} m da ${label}`); }
      else if (meters <= 700) { score += 7; reasons.push(`fica relativamente perto da ${label}`); }
      else if (meters >= 1800) score -= 8;
    }
  }
  return { score, reasons };
}

function estimatedWaitAtMinute(meta, minute, nowMin) {
  if (meta.activity.type !== 'attraction') return 0;
  const live = Number.isFinite(meta.liveWait) ? Number(meta.liveWait) : null;
  const planned = Number.isFinite(meta.plannedWait) ? Number(meta.plannedWait) : null;
  const base = live ?? planned ?? 30;
  const horizon = Math.max(0, Number(minute || nowMin) - Number(nowMin || 0));
  const blend = Math.min(.82, horizon / 240);
  let estimate = live != null && planned != null ? live * (1-blend) + planned * blend : base;
  const hour = Math.floor(Number(minute || 0) / 60);
  let dayFactor = 1;
  if (hour < 10) dayFactor = .86;
  else if (hour < 13) dayFactor = 1.10;
  else if (hour < 16) dayFactor = 1.05;
  else if (hour < 18) dayFactor = .96;
  else if (hour < 20) dayFactor = .82;
  else dayFactor = .72;
  estimate *= dayFactor;
  return Math.max(5, Math.round(estimate / 5) * 5);
}

function replanCandidateMeta(activity, livePayload, weatherPayload, nowMin) {
  const live = livePayload?.liveData || [];
  const liveWait = extractStandby(findLiveMatch(activity, live));
  const plannedWait = Number.isFinite(Number(activity.plannedWait)) ? Number(activity.plannedWait) : null;
  const wait = activity.type === 'attraction' ? (liveWait ?? plannedWait ?? 25) : 0;
  const weather = relevantWeather(weatherPayload);
  const wasSkipped = isSkipped(activity.id) && activity.type === 'attraction';
  let score = Number(activity.priority || 3) * 24 - wait * .62;
  const reasons = [];

  if (wasSkipped) {
    score += 38;
    reasons.push('atração pulada: prioridade de recuperação');
  }
  if (liveWait != null && plannedWait != null && liveWait <= plannedWait - 10) {
    score += 22;
    reasons.push(`fila caiu de ${plannedWait} para ${liveWait} min`);
  } else if (liveWait != null && liveWait <= 20) {
    score += 16;
    reasons.push(`fila baixa agora (${liveWait} min)`);
  } else if (liveWait != null && liveWait >= Number(state.settings.longWaitThreshold || 60)) {
    score -= 24;
    reasons.push(`fila alta agora (${liveWait} min)`);
  }

  if (activity.weatherSensitive && weather.nextRisk && weather.risk.score === 0) {
    score += 24;
    reasons.push(`vale priorizar antes do risco às ${weather.nextRisk.time.slice(11,16)}`);
  }
  if (activity.weatherSensitive && weather.risk.score > 0) {
    score -= 38;
    reasons.push('atração exposta ao mau tempo agora');
  }
  if (activity.indoor && weather.risk.score > 0) {
    score += 24;
    reasons.push('opção coberta favorecida pelo clima');
  }
  if (timeToMinutes(activity.time) < nowMin) {
    score += Math.min(14, (nowMin - timeToMinutes(activity.time)) * .06);
    reasons.push('já estava prevista no roteiro');
  }
  if (activity.replanDeferred) score += 3;

  const travelBuffer = activity.type === 'travel' ? 0 : 10;
  const estimatedMinutes = Math.max(5, wait + Number(activity.duration || 10) + travelBuffer);
  return { activity, liveWait, plannedWait, wait, score, reasons, estimatedMinutes, wasSkipped };
}

function generateReplanProposal(day, livePayload, weatherPayload, force = false) {
  if (!day) return null;
  const triggers = getReplanTriggers(day, livePayload, weatherPayload);
  if (!triggers.length && !force) return null;

  const pendingNormal = (day.activities || []).filter(a => !isDone(a.id) && !isSkipped(a.id));
  const skippedRecoverable = (day.activities || []).filter(a => a.type === 'attraction' && isSkipped(a.id) && !isDone(a.id));
  const pendingMap = new Map([...pendingNormal, ...skippedRecoverable].map(a => [a.id,a]));
  const pending = [...pendingMap.values()];
  if (!pending.length) return null;

  const now = getOrlandoParts();
  const today = day.date === now.date;
  const nowMin = today ? now.hour * 60 + now.minute : Math.min(...pending.map(a => timeToMinutes(a.time)));
  let cursor = Math.min(1430, nowMin + (today ? 5 : 0));
  const original = getOriginalActivities(day);
  const originalMap = new Map(original.map(a => [a.id, a]));
  const scheduled = [];
  const explanationSeed = [];

  const pastFixed = pendingNormal
    .filter(a => !a.flexible && timeToMinutes(a.time) < cursor)
    .sort((a,b) => timeToMinutes(a.time) - timeToMinutes(b.time));

  for (const activity of pastFixed) {
    const start = cursor;
    scheduled.push({ id:activity.id, activity, time:minutesToTime(start), originalTime:originalMap.get(activity.id)?.time || activity.time, fixed:true, movedFixed:true, wait:null, predictedWait:null, estimatedMinutes:Number(activity.duration || 20) });
    cursor += Number(activity.duration || 20) + 5;
    explanationSeed.push({ tone:'warn', title:`${activity.title}: horário fixo já passou`, detail:`reencaixado às ${minutesToTime(start)}; confirme disponibilidade se houver reserva ou janela de entrada.` });
  }

  const futureFixed = pendingNormal
    .filter(a => !a.flexible && !pastFixed.some(p => p.id === a.id))
    .sort((a,b) => timeToMinutes(a.time) - timeToMinutes(b.time));

  let flexible = pending
    .filter(a => a.flexible || skippedRecoverable.some(s => s.id === a.id))
    .map(a => replanCandidateMeta(a, livePayload, weatherPayload, nowMin));

  function slotScore(meta, slotStart, blockEnd, nextActivity) {
    const predictedWait = estimatedWaitAtMinute(meta, slotStart, nowMin);
    const dynamicMinutes = Math.max(5, predictedWait + Number(meta.activity.duration || 10) + 10);
    if (slotStart + dynamicMinutes > blockEnd) return null;

    const prevActivity = scheduled.length ? scheduled[scheduled.length-1].activity : null;
    const proximity = proximityMeta(meta.activity, prevActivity, nextActivity);
    const hourWeather = weatherAtMinute(weatherPayload, slotStart, day.date);
    const slotRisk = weatherRiskForHour(hourWeather);
    let score = meta.score - Math.max(0, predictedWait - Number(meta.wait || predictedWait)) * .35 + proximity.score;
    const slotReasons = [...meta.reasons, ...proximity.reasons];

    if (meta.activity.weatherSensitive && slotRisk.score > 0) {
      score -= slotRisk.level === 'high' ? 42 : 24;
      slotReasons.push(`risco de clima ${slotRisk.label} nesse horário`);
    } else if (meta.activity.weatherSensitive && slotRisk.score === 0) {
      score += 7;
      slotReasons.push('janela de clima mais segura');
    }
    if (meta.activity.indoor && slotRisk.score > 0) {
      score += 14;
      slotReasons.push('atração coberta encaixa bem com o clima previsto');
    }
    if (meta.wasSkipped) score += 18;

    return { score, predictedWait, dynamicMinutes, slotRisk, proximity, slotReasons };
  }

  function fillBlock(blockEnd, nextActivity = null) {
    let safety = 0;
    while (flexible.length && safety++ < 100) {
      const choices = flexible
        .map(meta => ({ meta, slot:slotScore(meta, cursor, blockEnd, nextActivity) }))
        .filter(x => x.slot)
        .sort((a,b) => b.slot.score - a.slot.score || timeToMinutes(a.meta.activity.time) - timeToMinutes(b.meta.activity.time));
      if (!choices.length) break;
      const {meta:choice, slot} = choices[0];
      scheduled.push({
        id:choice.activity.id,
        activity:choice.activity,
        time:minutesToTime(cursor),
        originalTime:originalMap.get(choice.activity.id)?.time || choice.activity.time,
        fixed:false,
        movedFixed:false,
        wait:choice.liveWait,
        predictedWait:slot.predictedWait,
        plannedWait:choice.plannedWait,
        reasons:slot.slotReasons,
        estimatedMinutes:slot.dynamicMinutes,
        wasSkipped:choice.wasSkipped,
        blockEnd:minutesToTime(blockEnd),
        proximityReasons:slot.proximity.reasons,
        weatherRisk:slot.slotRisk
      });
      cursor += slot.dynamicMinutes;
      flexible = flexible.filter(x => x.activity.id !== choice.activity.id);
    }
  }

  for (const fixed of futureFixed) {
    const fixedMin = timeToMinutes(fixed.time);
    fillBlock(Math.max(cursor, fixedMin - 10), fixed);
    if (cursor > fixedMin) explanationSeed.push({ tone:'warn', title:`Janela apertada antes de ${fixed.title}`, detail:`o compromisso continua às ${fixed.time}; evite adicionar novas atrações até lá.` });
    scheduled.push({ id:fixed.id, activity:fixed, time:fixed.time, originalTime:originalMap.get(fixed.id)?.time || fixed.time, fixed:true, movedFixed:false, wait:null, predictedWait:null, estimatedMinutes:Number(fixed.duration || 20) });
    explanationSeed.push({ tone:'good', title:`${fixed.title} preservado`, detail:`horário fixo mantido às ${fixed.time}.` });
    cursor = Math.max(cursor, fixedMin + Number(fixed.duration || 20));
  }

  const latestOriginal = Math.max(...pending.map(a => timeToMinutes(a.time) + Number(a.duration || 10)), 0);
  const dayEnd = Math.min(1430, Math.max(1350, latestOriginal + 60, cursor + 180));
  fillBlock(dayEnd, null);

  const deferred = flexible
    .sort((a,b) => b.score - a.score)
    .map(meta => ({ id:meta.activity.id, activity:meta.activity, originalTime:originalMap.get(meta.activity.id)?.time || meta.activity.time, wait:meta.liveWait, predictedWait:estimatedWaitAtMinute(meta, dayEnd, nowMin), plannedWait:meta.plannedWait, reasons:meta.reasons, wasSkipped:meta.wasSkipped }));

  const weather = relevantWeather(weatherPayload);
  const explanations = [...explanationSeed];
  for (const item of scheduled.filter(x => !x.fixed)) {
    const originalMin = timeToMinutes(item.originalTime);
    const newMin = timeToMinutes(item.time);
    const delta = newMin - originalMin;
    let detail = item.reasons?.[0] || 'melhor encaixe no bloco atual, preservando compromissos fixos.';
    if (item.wasSkipped) {
      const extras = [];
      if (item.predictedWait != null) extras.push(`fila estimada de ${item.predictedWait} min`);
      if (item.proximityReasons?.length) extras.push(item.proximityReasons[0]);
      if (item.activity.weatherSensitive && item.weatherRisk?.score === 0) extras.push('janela de clima mais segura');
      detail = `sugestão: encaixar às ${item.time}${extras.length ? `, ${extras.join('; ')}` : ''}.`;
      explanations.push({ tone:'good', title:`${item.activity.title} reencaixada após ser pulada`, detail });
      continue;
    }
    if (item.wait != null && item.plannedWait != null && item.wait <= item.plannedWait - 10) detail = `fila caiu de ${item.plannedWait} para ${item.wait} min.`;
    else if (item.activity.weatherSensitive && weather.nextRisk && newMin < timeToMinutes(weather.nextRisk.time.slice(11,16))) detail = `priorizada antes do risco de tempo por volta de ${weather.nextRisk.time.slice(11,16)}.`;
    else if (item.predictedWait != null && item.wait != null && item.predictedWait <= item.wait - 10) detail = `fila estimada de ${item.predictedWait} min nesse horário, contra ${item.wait} min agora.`;
    else if (item.wait != null && item.wait >= Number(state.settings.longWaitThreshold || 60)) detail = `fila atual de ${item.wait} min; foi empurrada para um bloco posterior.`;

    if (delta <= -15) explanations.push({ tone:'good', title:`${item.activity.title} antecipada`, detail });
    else if (delta >= 15) explanations.push({ tone:'good', title:`${item.activity.title} movida`, detail });
  }
  for (const item of deferred) {
    if (item.wasSkipped) {
      explanations.push({ tone:'warn', title:`${item.activity.title} pulada`, detail:`não foi encontrado um bloco seguro sem impactar o restante do roteiro; manter como opção para o fim do dia${item.predictedWait != null ? `, com fila estimada de ${item.predictedWait} min` : ''}.` });
    } else {
      explanations.push({ tone:'warn', title:`${item.activity.title} não cabe no bloco atual`, detail:'mantida como opção para o fim do dia; o plano principal não dependerá dela.' });
    }
  }

  const uniqueExplanations = [];
  const seen = new Set();
  for (const item of explanations) {
    const key = `${item.title}|${item.detail}`;
    if (!seen.has(key)) { seen.add(key); uniqueExplanations.push(item); }
  }

  const originalPending = pending
    .map(a => ({ id:a.id, title:a.title, time:originalMap.get(a.id)?.time || a.time, fixed:!a.flexible, skipped:isSkipped(a.id) }))
    .sort((a,b) => timeToMinutes(a.time) - timeToMinutes(b.time));
  const proposed = [...scheduled]
    .sort((a,b) => timeToMinutes(a.time) - timeToMinutes(b.time))
    .map(a => ({ id:a.id, title:a.activity.title, time:a.time, fixed:a.fixed, deferred:false, recoveredSkipped:Boolean(a.wasSkipped), predictedWait:a.predictedWait }));
  deferred.forEach(a => proposed.push({ id:a.id, title:a.activity.title, time:'Fim', fixed:false, deferred:true, recoveredSkipped:Boolean(a.wasSkipped), predictedWait:a.predictedWait }));

  const status = currentPlanStatus(day);
  let summary = 'A ordem foi recalculada usando prioridade, filas atuais/estimadas, clima, proximidade e horários fixos.';
  if (skippedRecoverable.length) summary = `${skippedRecoverable.length} atração(ões) pulada(s) foram reavaliadas. O app procura janelas livres e tenta reencaixá-las sem comprometer o restante do dia.`;
  else if (status.delay > Number(state.settings.delayThreshold || 15)) summary = `Vocês estão ${status.delay} min atrasados. O novo plano reorganiza o restante do dia sem alterar compromissos fixos futuros.`;
  else if (triggers.some(t => t.type === 'weather')) summary = 'O clima mudou. O novo plano favorece atrações cobertas ou antecipa atrações sensíveis ao tempo.';
  else if (triggers.some(t => t.type === 'wait')) summary = 'Uma ou mais filas ficaram acima do limite. O novo plano procura melhores encaixes sem perder prioridades.';

  return {
    date: day.date,
    generatedAt: Date.now(),
    triggers,
    signature: replanSignature(day, triggers.length ? triggers : [{ type:'manual', value:Math.floor(Date.now()/300000), label:'Análise manual' }]),
    summary,
    original: originalPending,
    proposed,
    scheduled,
    deferred,
    waitEstimateMethod:'heuristic-live-plus-planned-and-daypart',
    explanations: uniqueExplanations.slice(0, 12)
  };
}


function buildReplanComparisonJson(proposal) {
  if (!proposal) return null;
  const adjustments = {};
  const changes = [];
  const titles = (proposal.original || []).map(x=>x.title).sort((a,b)=>b.length-a.length);

  for (const explanation of proposal.explanations || []) {
    const matchedTitle = titles.find(title => explanation.title.startsWith(title)) || explanation.title;
    const actionRaw = explanation.title.slice(matchedTitle.length).replace(/^[\s:–-]+/, '').trim();
    const action = actionRaw || (explanation.tone === 'warn' ? 'atenção' : 'ajustada');
    const symbol = explanation.tone === 'warn' ? '⚠' : '✓';
    const text = `${symbol} ${action} - ${String(explanation.detail || '').replace(/\.$/,'')}`;
    let key = matchedTitle;
    let n = 2;
    while (Object.prototype.hasOwnProperty.call(adjustments, key)) key = `${matchedTitle} (${n++})`;
    adjustments[key] = text;
    changes.push({ activity:matchedTitle, status:explanation.tone, action, explanation:explanation.detail, message:text });
  }

  return {
    schemaVersion: 2,
    type: 'orlando-flow-replan-comparison',
    generatedAt: new Date(proposal.generatedAt).toISOString(),
    date: proposal.date,
    causes: (proposal.triggers || []).map(t=>({ type:t.type, severity:t.severity, description:t.label })),
    summary: proposal.summary,
    originalRoute: (proposal.original || []).map(x=>({ id:x.id, time:x.time, activity:x.title, fixed:Boolean(x.fixed), skipped:Boolean(x.skipped) })),
    suggestedRoute: (proposal.proposed || []).map(x=>({ id:x.id, time:x.time, activity:x.title, fixed:Boolean(x.fixed), endOfDayOption:Boolean(x.deferred), recoveredSkipped:Boolean(x.recoveredSkipped), estimatedWaitMinutes:x.predictedWait ?? null })),
    waitEstimateMethod: proposal.waitEstimateMethod || null,
    skippedRecovery: [
      ...(proposal.scheduled || []).filter(x=>x.wasSkipped).map(x=>({
        id:x.id, activity:x.activity.title, status:'reinserted', suggestedTime:x.time, estimatedWaitMinutes:x.predictedWait ?? null,
        blockEnd:x.blockEnd || null, proximityNotes:x.proximityReasons || [], weatherRisk:x.weatherRisk?.label || 'baixo'
      })),
      ...(proposal.deferred || []).filter(x=>x.wasSkipped).map(x=>({
        id:x.id, activity:x.activity.title, status:'end-of-day-option', suggestedTime:null, estimatedWaitMinutes:x.predictedWait ?? null,
        blockEnd:null, proximityNotes:[], weatherRisk:null
      }))
    ],
    adjustments,
    changes
  };
}

function persistReplanAnalysis(proposal) {
  if (!proposal) return null;
  const comparison = buildReplanComparisonJson(proposal);
  currentReplanJson = comparison;
  state.lastReplanAnalyses[proposal.date] = comparison;
  return comparison;
}

function logReplanDecision(action, proposal) {
  if (!proposal) return;
  const analysis = persistReplanAnalysis(proposal);
  state.replanHistory.push({
    date:proposal.date,
    action,
    at:new Date().toISOString(),
    signature:proposal.signature,
    causes:structuredClone(analysis?.causes || []),
    adjustments:structuredClone(analysis?.adjustments || {})
  });
  if (state.replanHistory.length > 100) state.replanHistory = state.replanHistory.slice(-100);
}

function downloadCurrentReplanJson() {
  const proposal = currentReplanProposal;
  const data = proposal ? persistReplanAnalysis(proposal) : state.lastReplanAnalyses?.[state.selectedDate];
  if (!data) {
    toast('Nenhuma análise de replanejamento disponível.');
    return;
  }
  downloadBlob(`replanejamento-${data.date}-${new Date(data.generatedAt).getTime()}.json`, new Blob([JSON.stringify(data,null,2)], {type:'application/json'}));
}

function renderReplanPanel(day, livePayload, weatherPayload) {
  const panel = $('#replanPanel');
  if (!panel) return;
  const samePark = day?.park === state.selectedPark;
  if (!day || !samePark || day.park === 'off-day') {
    currentReplanProposal = null;
    panel.hidden = true;
    return;
  }
  panel.hidden = false;

  const proposal = generateReplanProposal(day, livePayload, weatherPayload, forceReplanAnalysis);
  currentReplanProposal = proposal;
  const title = $('#replanTitle');
  const badge = $('#replanBadge');
  const triggersEl = $('#replanTriggers');
  const summary = $('#replanSummary');
  const comparison = $('#replanComparison');
  const explanations = $('#replanExplanations');
  const actions = $('#replanActions');
  const analyze = $('#analyzeReplanBtn');
  const jsonBtn = $('#downloadReplanJsonBtn');

  if (!proposal) {
    panel.className = 'replan-panel stable';
    title.textContent = 'Roteiro estável agora';
    badge.textContent = 'SEM AJUSTE';
    badge.className = 'replan-badge good';
    triggersEl.innerHTML = '';
    summary.textContent = 'Não encontrei atraso, fila crítica ou risco de tempo que justifique mudar o plano neste momento.';
    comparison.innerHTML = '';
    explanations.innerHTML = '';
    actions.hidden = true;
    analyze.hidden = false;
    jsonBtn.hidden = true;
    currentReplanJson = null;
    return;
  }

  const decision = state.replanDecisions?.[day.date];
  if (!forceReplanAnalysis && decision?.signature === proposal.signature && Date.now() - Number(decision.at || 0) < 30 * 60 * 1000) {
    panel.className = 'replan-panel decision';
    title.textContent = decision.action === 'applied' ? 'Novo roteiro aplicado' : 'Roteiro original mantido';
    badge.textContent = decision.action === 'applied' ? 'APLICADO' : 'MANTIDO';
    badge.className = `replan-badge ${decision.action === 'applied' ? 'good' : 'neutral'}`;
    triggersEl.innerHTML = proposal.triggers.map(t => `<span class="replan-trigger ${t.severity}">${escapeHtml(t.label)}</span>`).join('');
    summary.textContent = decision.action === 'applied' ? 'A timeline já está usando a última sugestão aceita. Você pode analisar novamente se a situação mudou.' : 'Nenhuma alteração foi aplicada. Você pode analisar novamente a qualquer momento.';
    comparison.innerHTML = '';
    explanations.innerHTML = '';
    actions.hidden = true;
    analyze.hidden = false;
    currentReplanJson = state.lastReplanAnalyses?.[day.date] || buildReplanComparisonJson(proposal);
    jsonBtn.hidden = !currentReplanJson;
    return;
  }

  panel.className = 'replan-panel active';
  title.textContent = 'Replanejamento recomendado';
  badge.textContent = 'ANÁLISE';
  badge.className = 'replan-badge warn';
  triggersEl.innerHTML = proposal.triggers.length
    ? proposal.triggers.map(t => `<span class="replan-trigger ${t.severity}">${escapeHtml(t.label)}</span>`).join('')
    : '<span class="replan-trigger manual">Análise manual</span>';
  summary.textContent = proposal.summary;

  const renderPlan = (label, items, proposed = false) => `<div class="plan-column"><div class="plan-column-head"><span>${label}</span><small>${items.length} itens</small></div><div class="plan-list">${items.map(item => `<div class="plan-row ${item.deferred ? 'deferred' : ''}"><span class="plan-time">${escapeHtml(item.time)}</span><span class="plan-name">${escapeHtml(item.title)}</span>${item.skipped ? '<span class="plan-tag optional">pulada</span>' : item.fixed ? '<span class="plan-tag">fixo</span>' : item.deferred ? '<span class="plan-tag optional">opção</span>' : item.recoveredSkipped ? '<span class="plan-tag suggested">reencaixada</span>' : proposed ? '<span class="plan-tag suggested">novo</span>' : ''}</div>`).join('')}</div></div>`;
  comparison.innerHTML = `${renderPlan('Roteiro original', proposal.original)}<div class="replan-arrow" aria-hidden="true">→</div>${renderPlan('Nova sugestão', proposal.proposed, true)}`;

  explanations.innerHTML = proposal.explanations.length
    ? proposal.explanations.map(item => `<div class="replan-explanation ${item.tone}"><span class="replan-explanation-icon" aria-hidden="true">${item.tone === 'warn' ? '⚠' : '✓'}</span><div><strong>${escapeHtml(item.title)}</strong><small>${escapeHtml(item.detail)}</small></div></div>`).join('')
    : '<div class="source-note">A ordem sugerida prioriza os melhores encaixes disponíveis agora.</div>';
  actions.hidden = false;
  analyze.hidden = true;
  persistReplanAnalysis(proposal);
  jsonBtn.hidden = false;
}

function restoreOriginalPlanForDate(date) {
  const day = state.days.find(d => d.date === date);
  const original = state.originalPlans?.[date];
  if (!day || !Array.isArray(original)) return;
  const currentMap = new Map((day.activities || []).map(a => [a.id, a]));
  const restored = original.map(base => {
    const current = currentMap.get(base.id) || base;
    const clone = { ...current, time:base.time, flexible:base.flexible, replanDeferred:false };
    delete clone.originalIndex;
    return clone;
  });
  for (const current of day.activities || []) if (!restored.some(a => a.id === current.id)) restored.push({ ...current, replanDeferred:false });
  day.activities = restored;
}

function keepOriginalRoute() {
  const day = getSelectedDay();
  if (!day || !currentReplanProposal) return;
  restoreOriginalPlanForDate(day.date);
  state.replanDecisions[day.date] = { action:'kept', signature:currentReplanProposal.signature, at:Date.now() };
  logReplanDecision('kept', currentReplanProposal);
  forceReplanAnalysis = false;
  saveState();
  renderAll();
  toast('Roteiro original mantido. Nenhuma sugestão foi aplicada.');
}

function applyReplanProposal() {
  const day = getSelectedDay();
  const proposal = currentReplanProposal;
  if (!day || !proposal || proposal.date !== day.date) return;
  ensureOriginalPlans();
  const currentMap = new Map(day.activities.map(a => [a.id, a]));
  const scheduledMap = new Map(proposal.scheduled.map(item => [item.id, item]));
  const deferredIds = new Set(proposal.deferred.map(item => item.id));
  const recoveredSkippedIds = new Set(
    [...proposal.scheduled, ...proposal.deferred]
      .filter(item => item.wasSkipped || isSkipped(item.id))
      .map(item => item.id)
  );
  const completed = day.activities.filter(a => isDone(a.id) || (isSkipped(a.id) && !recoveredSkippedIds.has(a.id)));
  const pendingScheduled = proposal.scheduled.map(item => {
    const current = currentMap.get(item.id) || item.activity;
    return { ...current, time:item.time, replanDeferred:false, replanGeneratedAt:new Date(proposal.generatedAt).toISOString() };
  });
  const pendingDeferred = proposal.deferred.map(item => {
    const current = currentMap.get(item.id) || item.activity;
    return { ...current, replanDeferred:true, replanGeneratedAt:new Date(proposal.generatedAt).toISOString() };
  });
  const extras = day.activities.filter(a => !completed.some(x => x.id === a.id) && !scheduledMap.has(a.id) && !deferredIds.has(a.id));

  if (recoveredSkippedIds.size) {
    state.history = state.history.map(h => {
      if (h.status === 'skipped' && h.date === day.date && recoveredSkippedIds.has(h.activityId)) {
        return { ...h, status:'rescheduled', rescheduledAt:new Date().toISOString(), replanGeneratedAt:new Date(proposal.generatedAt).toISOString() };
      }
      return h;
    });
  }

  day.activities = [...completed, ...pendingScheduled, ...extras, ...pendingDeferred];
  state.replanDecisions[day.date] = { action:'applied', signature:proposal.signature, at:Date.now() };
  logReplanDecision('applied', proposal);
  forceReplanAnalysis = false;
  saveState();
  renderAll();
  switchView('today');
  toast(recoveredSkippedIds.size ? `${recoveredSkippedIds.size} atração(ões) pulada(s) voltaram ao roteiro.` : 'Novo roteiro aplicado à linha do tempo.');
}

function smartNoteForActivity(activity, livePayload, weatherPayload) {
  const notes = [];
  const live = livePayload?.liveData || [];
  const match = findLiveMatch(activity, live);
  const wait = extractStandby(match);
  if (wait != null) notes.push(`Fila ao vivo: ${wait} min.`);
  const w = relevantWeather(weatherPayload);
  if (activity.weatherSensitive && w.risk.score > 0) notes.push('Atração sensível ao tempo: considere trocar por uma opção coberta agora.');
  else if (activity.weatherSensitive && w.nextRisk) notes.push(`Há risco de piora por volta de ${w.nextRisk.time.slice(11,16)}; priorizar esta atração pode fazer sentido.`);
  if (wait != null && wait >= Number(state.settings.longWaitThreshold || 60)) notes.push('Fila acima do limite configurado; veja a aba Ao vivo para alternativas.');
  return notes.join(' ');
}

function renderHeader() {
  const day = getSelectedDay();
  $('#tripLabel').textContent = state.tripName || 'ORLANDO FLOW';
  $('#dayTitle').textContent = day ? `${formatDate(day.date)} · ${day.label}` : 'Hoje';
  $('#orlandoClock').textContent = getOrlandoParts().time;
  applyParkTheme();
}

function renderDaySelect() {
  const select = $('#daySelect');
  select.innerHTML = state.days.map(d => `<option value="${d.date}" ${d.date===state.selectedDate?'selected':''}>${formatDate(d.date,true)} · ${escapeHtml(d.label)}</option>`).join('');
}

function renderStatus() {
  const day = getSelectedDay();
  const s = currentPlanStatus(day);
  const total = day?.activities?.length || 0;
  $('#planStatus').textContent = s.status;
  $('#statusDetail').textContent = s.detail;
  $('#doneCount').textContent = s.done;
  $('#pendingCount').textContent = s.pending;
  $('#delayValue').textContent = s.delay > 0 ? `+${s.delay}` : s.delay;
  $('#dayProgress').style.width = `${total ? Math.round((s.done/total)*100) : 0}%`;
  $('#statusCard').classList.toggle('bad', s.level === 'bad');
  $('#statusCard').classList.toggle('warn', s.level === 'warn');
  const triggers = getReplanTriggers(day, state.liveCache[day?.park], state.weatherCache[day?.park]);
  $('#optimizeBtn').textContent = triggers.length ? 'Replanejar' : 'Otimizar';
}

function renderWeather() {
  const weather = state.weatherCache[state.selectedPark];
  if (!weather) {
    $('#weatherHeadline').textContent = 'Clima não consultado';
    $('#weatherDetail').textContent = 'Toque em atualizar para buscar a previsão.';
    $('#weatherRisk').textContent = '--';
    $('#weatherRisk').className = 'risk-badge';
    return;
  }
  const r = relevantWeather(weather);
  const temp = weather.current?.temperature_2m ?? r.current?.temperature_2m;
  const code = weather.current?.weather_code ?? r.current?.weather_code;
  const pp = r.current?.precipitation_probability ?? 0;
  $('#weatherHeadline').textContent = `${Math.round(temp ?? 0)}°C · ${weatherCodeText(code)}`;
  $('#weatherDetail').textContent = r.nextRisk ? `${pp}% chuva agora · atenção por volta de ${r.nextRisk.time.slice(11,16)}` : `${pp}% chance de chuva · sem alerta forte nas próximas horas`;
  $('#weatherRisk').textContent = `risco ${r.risk.label}`;
  $('#weatherRisk').className = `risk-badge ${r.risk.level}`;
  $('.weather-icon').textContent = [95,96,99].includes(code) ? 'ϟ' : pp >= 45 ? '☂' : '☀︎';
}

function renderNext() {
  const day = getSelectedDay();
  const next = day?.activities?.find(a => !a.replanDeferred && !isDone(a.id) && !isSkipped(a.id));
  if (!next) { $('#nextCard').className='next-card empty'; $('#nextCard').textContent='Nenhuma atividade pendente neste dia.'; return; }
  const live = state.liveCache[day.park];
  const weather = state.weatherCache[day.park];
  const note = smartNoteForActivity(next, live, weather);
  const status = isStarted(next.id) ? 'Em andamento' : next.flexible ? 'Flexível' : 'Horário fixo';
  $('#nextCard').className='next-card';
  $('#nextCard').innerHTML = `
    <div class="next-head"><div><span class="kicker">${escapeHtml(status)}</span><div class="next-title">${escapeHtml(next.title)}</div><div class="muted">${escapeHtml(next.area || next.type || '')}</div></div><span class="time-chip">${escapeHtml(next.time)}</span></div>
    <div class="meta-row"><span class="meta-chip">${next.indoor?'coberta':'ao ar livre'}</span><span class="meta-chip">prioridade ${next.priority || 3}/5</span>${next.plannedWait!=null?`<span class="meta-chip">fila planejada ${next.plannedWait}m</span>`:''}</div>
    ${note ? `<div class="smart-note">${escapeHtml(note)}</div>` : ''}
    <div class="button-row"><button class="secondary-btn" data-start="${next.id}">${isStarted(next.id)?'Já iniciada':'Iniciar'}</button><button class="primary-btn" data-complete="${next.id}">Concluir</button></div>`;
}

function renderTimeline() {
  const day = getSelectedDay();
  const items = day?.activities || [];
  $('#timeline').innerHTML = items.map(a => {
    const done = isDone(a.id), skipped = isSkipped(a.id), started = isStarted(a.id);
    const log = getActivityLog(a.id);
    const cls = done?'done':started?'started':'';
    const subtitle = skipped ? 'Pulada' : done ? `Concluída ${formatTimeISO(log?.actualEnd)}${log?.rating?` · ${formatRating(log.rating, true)}`:''}` : a.replanDeferred ? `${a.area || a.type} · opção para o fim do dia` : `${a.area || a.type}${a.flexible?' · flexível':' · fixo'}`;
    return `<div class="timeline-item ${cls} ${a.replanDeferred?'deferred':''}">
      <div class="timeline-time">${a.replanDeferred?'OPÇÃO':escapeHtml(a.time)}</div><div class="timeline-rail"><span class="timeline-dot"></span></div>
      <div class="timeline-card"><strong>${escapeHtml(a.title)}</strong><small>${escapeHtml(subtitle)}</small>
      ${!done && !skipped ? `<div class="timeline-actions"><button data-start="${a.id}">${started?'em andamento':'iniciar'}</button><button data-complete="${a.id}">concluir</button><button class="danger" data-skip="${a.id}">pular</button></div>` : ''}
      </div></div>`;
  }).join('') || '<p class="muted">Sem atividades.</p>';
}

function renderParks() {
  const disneyKeys = ['magic-kingdom', 'epcot', 'hollywood-studios', 'animal-kingdom'];
  const universalKeys = ['universal-studios-florida', 'islands-of-adventure', 'epic-universe'];
  const options = keys => keys.map(key => `<option value="${key}" ${key===state.selectedPark?'selected':''}>${escapeHtml(PARKS[key].name)}</option>`).join('');
  $('#parkSelect').innerHTML = `<optgroup label="Disney Parks">${options(disneyKeys)}</optgroup><optgroup label="Universal Orlando">${options(universalKeys)}</optgroup>`;
}

function waitClass(wait) { return wait <= 30 ? 'good' : wait <= 60 ? 'warn' : 'bad'; }

function renderLive() {
  const payload = state.liveCache[state.selectedPark];
  const day = getSelectedDay();
  renderReplanPanel(day, payload, state.weatherCache[state.selectedPark]);
  if (!payload) {
    $('#liveStatus').textContent = 'Sem dados. Toque em Atualizar.';
    $('#waitList').innerHTML = '<p class="muted">Os tempos de fila aparecerão aqui.</p>';
    $('#recommendations').innerHTML = '';
    return;
  }
  const ageMin = Math.round((Date.now()-payload.fetchedAt)/60000);
  $('#liveStatus').textContent = `Última leitura: ${ageMin < 1 ? 'agora' : `${ageMin} min atrás`} · ThemeParks.wiki`;
  const limit = $('#waitFilter').value === 'all' ? Infinity : Number($('#waitFilter').value);
  const attractionQuery = normalizeName($('#liveAttractionSearch')?.value || '');
  const rows = payload.liveData
    .map(x => ({...x, wait:extractStandby(x)}))
    .filter(x => x.wait != null && x.wait <= limit)
    .filter(x => !attractionQuery || normalizeName(x.name).includes(attractionQuery))
    .sort((a,b) => a.wait-b.wait);
  $('#waitList').innerHTML = rows.map(x => `<div class="wait-row"><div><div class="wait-name">${escapeHtml(x.name)}</div><div class="wait-sub">${escapeHtml(x.status || 'status não informado')}</div></div><div class="wait-time ${waitClass(x.wait)}">${x.wait}m</div></div>`).join('') || '<p class="muted">Nenhuma atração com esse filtro.</p>';

  if (day?.park === state.selectedPark) {
    const recs = optimizeCandidates(day, payload, state.weatherCache[state.selectedPark]);
    $('#recommendations').innerHTML = recs.length ? recs.map((r,i) => `<div class="rec-card"><span class="kicker">Sugestão ${i+1}</span><strong>${escapeHtml(r.activity.title)} · ${r.wait} min</strong><div class="rec-reason">${escapeHtml(r.reasons.join(' · ') || 'boa relação entre prioridade e fila')}</div></div>`).join('') : '<div class="source-note">Sem troca clara para sugerir agora. Horários fixos e tempo disponível foram preservados.</div>';
  } else {
    $('#recommendations').innerHTML = '<div class="source-note">Selecione o mesmo parque do roteiro do dia para receber sugestões de reordenação.</div>';
  }
}

function activityForRecord(record) {
  return getActivityById(record.activityId, record.date) || { title:record.title || 'Atividade', type:record.type || 'other', duration:record.duration || 0 };
}

function recordType(record) {
  return String(activityForRecord(record)?.type || record.type || 'other').toLowerCase();
}

function isAttractionRecord(record) {
  return recordType(record) === 'attraction';
}

function isMealRecord(record) {
  return ['meal','restaurant','food'].includes(recordType(record));
}

function experienceMinutes(record, activity = activityForRecord(record)) {
  const planned = Number(activity?.duration || record.duration || 0);
  const start = record.actualStart ? new Date(record.actualStart).getTime() : NaN;
  const end = record.actualEnd ? new Date(record.actualEnd).getTime() : NaN;
  if (Number.isFinite(start) && Number.isFinite(end) && end > start) {
    const elapsed = Math.round((end - start) / 60000);
    if (isAttractionRecord(record)) return Math.max(planned, elapsed - Number(record.actualWait || 0));
    return Math.max(planned, elapsed);
  }
  return planned;
}

function restaurantNameFor(activity, record = null) {
  const recorded = String(record?.restaurantName || '').trim();
  if (recorded) return recorded;
  return activity?.restaurant || activity?.venue || activity?.restaurantName || 'Restaurante não informado';
}

function historyMetrics(records) {
  const attractionRecords = records.filter(isAttractionRecord);
  const waits = attractionRecords.map(r=>Number(r.actualWait||0));
  const ratings = records.map(r=>Number(r.rating||0)).filter(Boolean);
  const attractionMinutes = attractionRecords.reduce((sum,r)=>sum+experienceMinutes(r),0);
  return {
    count: records.length,
    attractionCount: attractionRecords.length,
    mealCount: records.filter(isMealRecord).length,
    wait: waits.reduce((a,b)=>a+b,0),
    avgWait: waits.length ? waits.reduce((a,b)=>a+b,0)/waits.length : 0,
    attractionMinutes,
    avgRating: ratings.length ? ratings.reduce((a,b)=>a+b,0)/ratings.length : 0
  };
}

function renderHistory() {
  const records = [...state.history].filter(r=>r.status==='done').sort((a,b)=>(b.actualEnd||'').localeCompare(a.actualEnd||''));
  const m = historyMetrics(records);
  const movement = movementMetricsForScope('trip');
  $('#historySummary').innerHTML = [
    ['Atividades',m.count],
    ['Atrações',m.attractionCount],
    ['Fila média',m.attractionCount?`${Math.round(m.avgWait)} min`:'--'],
    ['Passos',movement.steps?movement.steps.toLocaleString('pt-BR'):'--']
  ].map(([l,v])=>`<div class="summary-card"><b>${v}</b><span>${l}</span></div>`).join('');

  $('#historyList').innerHTML = records.map(r => {
    const a = activityForRecord(r);
    const type = String(a?.type || '').toLowerCase();
    const details = [formatDate(r.date)];
    if (type === 'attraction') details.push(`fila ${Number(r.actualWait||0)} min`);
    if (isMealRecord(r)) {
      const restaurant = restaurantNameFor(a, r);
      if (restaurant && restaurant !== 'Restaurante não informado') details.push(escapeHtml(restaurant));
      if (r.mealItem) details.push(escapeHtml(r.mealItem));
    }
    if (r.comment && !isMealRecord(r)) details.push(escapeHtml(r.comment));
    return `<div class="history-item"><div class="history-head"><strong>${escapeHtml(a?.title || r.title || 'Atividade')}</strong><span class="stars">${r.rating?formatRating(r.rating, true):''}</span></div><div class="history-meta">${details.join(' · ')}</div></div>`;
  }).join('') || '<p class="muted">Conclua atividades para formar o histórico.</p>';
}

function reportRecords() {
  const scope = $('#reportScope')?.value || 'day';
  return state.history.filter(r => r.status==='done' && (scope==='trip' || r.date===state.selectedDate));
}

function getActivityById(id, date) {
  return state.days.find(d=>d.date===date)?.activities.find(a=>a.id===id);
}

function replanEventsForScope(scope) {
  return (state.replanHistory || []).filter(event => scope === 'trip' || event.date === state.selectedDate);
}

function mostRepeatedAttraction(records) {
  const counts = new Map();
  for (const r of records.filter(isAttractionRecord)) {
    const name = activityForRecord(r)?.title || r.title || 'Atração';
    const key = normalizeName(name);
    const entry = counts.get(key) || { name, count:0 };
    entry.count += 1;
    counts.set(key, entry);
  }
  return [...counts.values()].sort((a,b)=>b.count-a.count || a.name.localeCompare(b.name))[0] || null;
}

function savedWaitMinutes(records) {
  return records.filter(isAttractionRecord).reduce((sum,r)=>{
    const a = activityForRecord(r);
    const planned = Number(a?.plannedWait);
    const actual = Number(r.actualWait);
    return sum + (Number.isFinite(planned) && Number.isFinite(actual) ? Math.max(0, planned-actual) : 0);
  },0);
}

function favoriteExperience(records) {
  return records
    .filter(r=>Number(r.rating||0)>0 && !['travel','transport','arrival'].includes(recordType(r)))
    .map(r=>({r,a:activityForRecord(r)}))
    .sort((x,y)=>Number(y.r.rating)-Number(x.r.rating) || Number(x.r.actualWait||0)-Number(y.r.actualWait||0))[0] || null;
}

function restaurantRanking(records) {
  const groups = new Map();
  for (const r of records.filter(isMealRecord)) {
    const a = activityForRecord(r);
    const name = restaurantNameFor(a, r);
    const key = normalizeName(name) || name;
    const item = groups.get(key) || {name, ratings:[], dishes:[], visits:0};
    item.visits += 1;
    if (Number(r.rating||0)) item.ratings.push(Number(r.rating));
    if (r.mealItem) item.dishes.push(r.mealItem);
    groups.set(key,item);
  }
  return [...groups.values()].map(x=>({
    ...x,
    avg:x.ratings.length?x.ratings.reduce((a,b)=>a+b,0)/x.ratings.length:0
  })).sort((a,b)=>b.avg-a.avg || b.visits-a.visits || a.name.localeCompare(b.name));
}

function dishRanking(records) {
  const groups = new Map();
  for (const r of records.filter(isMealRecord).filter(r=>r.mealItem)) {
    const name = r.mealItem.trim();
    const key = normalizeName(name) || name;
    const item = groups.get(key) || {name, ratings:[], count:0};
    item.count += 1;
    if (Number(r.rating||0)) item.ratings.push(Number(r.rating));
    groups.set(key,item);
  }
  return [...groups.values()].map(x=>({
    ...x,
    avg:x.ratings.length?x.ratings.reduce((a,b)=>a+b,0)/x.ratings.length:0
  })).sort((a,b)=>b.avg-a.avg || b.count-a.count || a.name.localeCompare(b.name));
}

function reportInsights(records, scope) {
  const m = historyMetrics(records);
  const repeated = mostRepeatedAttraction(records);
  const favorite = favoriteExperience(records);
  const replans = replanEventsForScope(scope);
  const applied = replans.filter(x=>x.action==='applied');
  const weatherReplans = applied.filter(x=>(x.causes||[]).some(c=>c.type==='weather'));
  const waitReplans = applied.filter(x=>(x.causes||[]).some(c=>c.type==='wait'));
  const delayedReplans = applied.filter(x=>(x.causes||[]).some(c=>c.type==='delay'));
  const weatherAffected = records.filter(r=>Number(r.weatherRiskAtCompletion?.score||0)>0).length;
  const saved = savedWaitMinutes(records);
  return {
    attractionMinutes:m.attractionMinutes,
    repeated,
    favorite,
    appliedReplans:applied.length,
    weatherReplans:weatherReplans.length,
    waitReplans:waitReplans.length,
    delayedReplans:delayedReplans.length,
    weatherAffected,
    savedWait:saved
  };
}

function parkKeyForRecord(record) {
  return state.days.find(d=>d.date===record.date)?.park || 'off-day';
}

function movementMetricsForDates(dates = []) {
  return [...new Set(dates.filter(Boolean))].reduce((acc,date)=>{
    const m = movementMetricsForDate(date);
    acc.distanceMeters += m.distanceMeters;
    acc.steps += m.steps;
    if (m.calories != null) acc.calories = (acc.calories ?? 0) + m.calories;
    return acc;
  }, {distanceMeters:0, steps:0, calories:null});
}

function reportGroupCard(title, records, { parkKey = null, brand = null, kicker = '' } = {}) {
  const m = historyMetrics(records);
  const dates = [...new Set(records.map(r=>r.date))];
  const movement = movementMetricsForDates(dates);
  const topAttractions = records.filter(r=>isAttractionRecord(r) && normalizeRating(r.rating))
    .map(r=>({r,a:activityForRecord(r)}))
    .sort((x,y)=>normalizeRating(y.r.rating)-normalizeRating(x.r.rating) || Number(x.r.actualWait||0)-Number(y.r.actualWait||0))
    .slice(0,3);
  const restaurants = restaurantRanking(records).slice(0,2);
  const favorite = favoriteExperience(records);
  const effectiveBrand = brand || getParkThemeConfig(parkKey || 'off-day').brand;
  const icon = parkKey
    ? `<span class="report-group-icon">${parkIconSvg(parkKey)}</span>`
    : effectiveBrand === 'disney'
      ? `<span class="report-group-icon"><span class="report-franchise-raster" style="--park-icon-url:url('${DISNEY_REPORT_LOGO}');width:31px;height:31px"><img src="${DISNEY_REPORT_LOGO}" alt=""></span></span>`
      : effectiveBrand === 'universal'
        ? `<span class="report-group-icon"><span class="report-franchise-raster" style="--park-icon-url:url('${UNIVERSAL_REPORT_LOGO}');width:38px;height:31px"><img src="${UNIVERSAL_REPORT_LOGO}" alt=""></span></span>`
        : `<span class="report-group-icon report-group-letter">O</span>`;
  const attractionsHtml = topAttractions.length
    ? topAttractions.map((x,i)=>`<div class="report-mini-rank"><b>${i+1}</b><span><strong>${escapeHtml(x.a?.title || x.r.title || 'Atração')}</strong><small>${formatRating(x.r.rating, true)} · fila ${Number(x.r.actualWait||0)} min</small></span></div>`).join('')
    : '<p class="muted report-empty">Sem atrações avaliadas ainda.</p>';
  const mealsHtml = restaurants.length
    ? restaurants.map((x,i)=>`<div class="report-mini-rank"><b>${i+1}</b><span><strong>${escapeHtml(x.name)}</strong><small>${x.avg?`${x.avg.toFixed(1).replace('.', ',')} ★`:''}${x.dishes.length?` · ${escapeHtml([...new Set(x.dishes)].slice(0,1).join(''))}`:''}</small></span></div>`).join('')
    : '<p class="muted report-empty">Sem refeições avaliadas.</p>';
  return `<article class="report-group-card" data-report-brand="${effectiveBrand}">
    <header class="report-group-head">${icon}<div><span class="kicker">${escapeHtml(kicker || FRANCHISE_LABELS[effectiveBrand] || 'Resumo')}</span><h4>${escapeHtml(title)}</h4></div></header>
    <div class="report-group-stats">
      <span><b>${m.attractionCount}</b><small>atrações</small></span>
      <span><b>${m.attractionCount?`${Math.round(m.avgWait)}m`:'--'}</b><small>fila média</small></span>
      <span><b>${m.avgRating?m.avgRating.toFixed(1).replace('.', ','):'--'}</b><small>nota média</small></span>
      <span><b>${movement.steps?movement.steps.toLocaleString('pt-BR'):'--'}</b><small>passos</small></span>
    </div>
    <div class="report-group-columns"><div><h5>Top atrações</h5>${attractionsHtml}</div><div><h5>Comidas</h5>${mealsHtml}</div></div>
    ${favorite?`<div class="report-group-highlight"><span>✨</span><div><small>experiência favorita</small><strong>${escapeHtml(favorite.a?.title || favorite.r.title || 'Experiência')} · ${formatRating(favorite.r.rating, true)}</strong></div></div>`:''}
  </article>`;
}

function renderReport() {
  const records = reportRecords();
  const m = historyMetrics(records);
  const scope = $('#reportScope').value;
  const movement = movementMetricsForScope(scope);
  const insights = reportInsights(records, scope);
  const title = scope==='trip' ? (state.tripName || 'Nossa viagem') : (getSelectedDay()?.label || 'Nosso dia');
  if ($('#reportOverallKicker')) $('#reportOverallKicker').textContent = scope==='trip' ? 'Geral da viagem' : 'Geral do dia';
  if ($('#reportOverallBadge')) $('#reportOverallBadge').textContent = scope==='trip' ? 'ALL PARKS' : 'DIA';
  const caloriesText = movement.calories == null ? '--' : `~${movement.calories.toLocaleString('pt-BR')}`;
  $('#reportHero').innerHTML = `<span class="kicker" style="color:#d1d5db">ORLANDO RECAP</span><div class="big">${escapeHtml(title)}</div><p style="margin:6px 0 0;color:#d1d5db">${m.attractionCount} atrações · ${Math.round(m.avgWait||0)} min de fila média · ${formatDistance(movement.distanceMeters)}</p>`;
  $('#reportStats').innerHTML = [
    ['Atrações',m.attractionCount],
    ['Distância',formatDistance(movement.distanceMeters)],
    ['Passos',movement.steps?movement.steps.toLocaleString('pt-BR'):'--'],
    ['Calorias',caloriesText]
  ].map(([l,v])=>`<div class="stat-card"><b>${v}</b><span>${l}</span></div>`).join('');

  const ranked = records.filter(r=>isAttractionRecord(r) && normalizeRating(r.rating)).map(r=>({r,a:activityForRecord(r)})).sort((x,y)=>normalizeRating(y.r.rating)-normalizeRating(x.r.rating) || Number(x.r.actualWait||0)-Number(y.r.actualWait||0));
  $('#rankingList').innerHTML = ranked.slice(0,10).map((x,i)=>`<div class="rank-row"><span class="rank-num">${i+1}</span><div><strong>${escapeHtml(x.a?.title || x.r.title || 'Atração')}</strong><div class="history-meta">${Number(x.r.actualWait||0)} min de fila${x.r.comment?` · ${escapeHtml(x.r.comment)}`:''}</div></div><span class="stars">${formatRating(x.r.rating, true)}</span></div>`).join('') || '<p class="muted">Avalie atrações concluídas para montar o ranking.</p>';

  const restaurants = restaurantRanking(records);
  const dishes = dishRanking(records);
  const mealRows = [
    ...restaurants.slice(0,5).map((x,i)=>`<div class="meal-rank-row"><span class="rank-num">${i+1}</span><div><strong>${escapeHtml(x.name)}</strong><div class="history-meta">${x.visits} visita${x.visits===1?'':'s'}${x.dishes.length?` · ${escapeHtml([...new Set(x.dishes)].slice(0,2).join(' / '))}`:''}</div></div><span class="stars">${x.avg?`${x.avg.toFixed(1).replace('.', ',')} ★`:'--'}</span></div>`),
    ...(dishes.length ? [`<div class="dish-highlight"><span>🍽️</span><div><strong>Prato favorito</strong><small>${escapeHtml(dishes[0].name)}${dishes[0].avg?` · ${dishes[0].avg.toFixed(1).replace('.', ',')} ★`:''}</small></div></div>`] : [])
  ];
  $('#mealRankingList').innerHTML = mealRows.join('') || '<p class="muted">Registre refeições e notas para criar o ranking gastronômico.</p>';

  const insightCards = [
    ['🎢', insights.attractionMinutes ? `${insights.attractionMinutes} min` : '--', 'tempo em atrações'],
    ['🔁', insights.repeated ? `${escapeHtml(insights.repeated.name)}${insights.repeated.count>1?` ×${insights.repeated.count}`:''}` : '--', 'mais repetida'],
    ['⏱️', m.attractionCount ? `${Math.round(m.avgWait)} min` : '--', 'fila média enfrentada'],
    ['✨', insights.favorite ? `${escapeHtml(insights.favorite.a?.title || insights.favorite.r.title)} · ${formatRating(insights.favorite.r.rating, true)}` : '--', 'experiência favorita'],
    ['🧠', insights.appliedReplans ? String(insights.appliedReplans) : '0', 'replanejamentos aplicados'],
    ['🌦️', String(insights.weatherReplans + insights.weatherAffected), 'impactos de clima registrados'],
    ['⚡', insights.savedWait ? `${insights.savedWait} min` : '0 min', 'fila poupada vs. planejado'],
    ['📍', formatDistance(movement.distanceMeters), 'distância por GPS']
  ];
  $('#insightsGrid').innerHTML = insightCards.map(([icon,v,l])=>`<div class="insight-card"><div>${icon}</div><b>${v}</b><span>${l}</span></div>`).join('');

  const best = ranked[0];
  const longest = [...records.filter(isAttractionRecord)].sort((a,b)=>Number(b.actualWait||0)-Number(a.actualWait||0))[0];
  const busiestDay = scope === 'trip'
    ? Object.entries(state.movementByDate || {}).map(([date])=>({date,m:movementMetricsForDate(date)})).sort((a,b)=>b.m.distanceMeters-a.m.distanceMeters)[0]
    : null;
  $('#funStats').innerHTML = [
    ['🏆', best ? (best.a?.title || 'Favorita') : '--', 'atração favorita'],
    ['⏳', longest ? `${longest.actualWait||0} min` : '--', 'maior fila vencida'],
    ['👟', movement.steps ? movement.steps.toLocaleString('pt-BR') : '--', 'passos estimados'],
    ['🔥', movement.calories == null ? '--' : `~${movement.calories} kcal`, 'calorias estimadas'],
    ['☔', insights.weatherReplans ? `${insights.weatherReplans} ajuste${insights.weatherReplans===1?'':'s'}` : '0 ajustes', 'por clima'],
    ['🗺️', busiestDay?.m?.distanceMeters ? `${formatDate(busiestDay.date,true)} · ${formatDistance(busiestDay.m.distanceMeters)}` : formatDistance(movement.distanceMeters), scope==='trip'?'dia mais caminhado':'distância do dia']
  ].map(([icon,v,l])=>`<div class="fun-card"><div>${icon}</div><b>${escapeHtml(String(v))}</b><span>${l}</span></div>`).join('') +
    '<small class="help-text">Passos e calorias são estimativas; a distância depende da qualidade do sinal GPS.</small>';

  const franchiseContainer = $('#franchiseReportSections');
  const parkContainer = $('#parkReportSections');
  if (franchiseContainer) {
    const franchiseCards = ['disney','universal'].map(brand=>{
      const subset = records.filter(r=>getParkThemeConfig(parkKeyForRecord(r)).brand===brand);
      return subset.length ? reportGroupCard(FRANCHISE_LABELS[brand], subset, {brand, kicker:'Franquia'}) : '';
    }).filter(Boolean);
    const neutralRecords = records.filter(r=>getParkThemeConfig(parkKeyForRecord(r)).brand==='neutral');
    if (neutralRecords.length) franchiseCards.push(reportGroupCard('Orlando / dias livres', neutralRecords, {brand:'neutral', kicker:'Fora dos parques'}));
    franchiseContainer.innerHTML = franchiseCards.join('') || '<p class="muted">Conclua experiências em Disney e Universal para comparar as franquias.</p>';
  }
  if (parkContainer) {
    const order = ['magic-kingdom','epcot','hollywood-studios','animal-kingdom','universal-studios-florida','islands-of-adventure','epic-universe','off-day'];
    parkContainer.innerHTML = order.map(parkKey=>{
      const subset = records.filter(r=>parkKeyForRecord(r)===parkKey);
      return subset.length ? reportGroupCard(PARKS[parkKey]?.name || 'Orlando', subset, {parkKey, kicker:'Parque'}) : '';
    }).filter(Boolean).join('') || '<p class="muted">Os cards por parque aparecem conforme vocês registram experiências.</p>';
  }
}

