  $('#tripNameInput').value = state.tripName || '';
  $('#delayThreshold').value = state.settings.delayThreshold || 15;
  $('#delayThresholdValue').textContent = `${state.settings.delayThreshold || 15} min`;
  $('#longWaitThreshold').value = state.settings.longWaitThreshold || 60;
  $('#longWaitThresholdValue').textContent = `${state.settings.longWaitThreshold || 60} min`;
  $('#strideCmInput').value = state.settings.strideCm || 75;
  $('#weightKgInput').value = state.settings.weightKg || '';
  $('#notificationBtn').textContent = ('Notification' in window && Notification.permission === 'granted') ? 'Notificações ativadas' : 'Ativar notificações';
  const settingsGps = $('#gpsSettingsBtn');
